entries[84557] = { ["name"] = "Formel: Armschiene - Große Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Große Beweglichkeit' durchführt.\nArmschienen dauerhaft verzaubern, sodass die Beweglichkeit um 7 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst von Pandaria (75)\nBenötigt Die Himmlischen Erhabenen\n- Respektvoll\nVerkaufspreis:" }
entries[84559] = { ["name"] = "Formel: Armschiene - Erstklassige Intelligenz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Erstklassige Intelligenz' durchführt.\nArmschienen dauerhaft verzaubern, sodass die Intelligenz um 7 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst von Pandaria (75)\nBenötigt Die Himmlischen Erhabenen\n- Respektvoll\nVerkaufspreis:" }
entries[84561] = { ["name"] = "Formel: Armschiene - Außergewöhnliche Stärke", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Außergewöhnliche Stärke' durchführt.\nArmschienen dauerhaft verzaubern, sodass die Stärke um 7 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst von Pandaria (75)\nBenötigt Die Himmlischen Erhabenen\n- Respektvoll\nVerkaufspreis:" }
entries[84580] = { ["name"] = "Formel: Waffe - Flussgesang", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Flussgesang' durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe manchmal Euer Ausweichen 7 Sek. lang um 34 erhöhen. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst von Pandaria (75)\nBenötigt Shado-Pan\n- Respektvoll\nVerkaufspreis:" }
entries[84582] = { ["name"] = "Formel: Waffe - Windweise", ["text"] = "Benötigt Verzauberkunst (550)\n\"Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass verursachter Zauber- und Nahkampfschaden den kritischen Trefferwert, das Tempo oder die Meisterschaft manchmal 12 Sek. lang um 1.500 erhöht. Erfordert einen Gegenstand der Stufe 372 oder höher.\"" }
entries[84583] = { ["name"] = "Formel: Waffe - Jadegeist", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Jadegeist' durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Heilungen oder Schaden verursachenden Zauber manchmal Eure Intelligenz um 34 erhöhen. Wenn Ihr über weniger als 25% Mana verfügt, während dieser Effekt ausgelöst wird, wird Eure Vielseitigkeit ebenfalls um 16 erhöht. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst von Pandaria (75)\nBenötigt Shado-Pan\n- Respektvoll\nVerkaufspreis:" }
entries[84584] = { ["name"] = "Formel: Waffe - Tanzender Stahl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch43 wie man die Verzauberung 'Tanzender Stahl' durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe manchmal Eure Stärke oder Beweglichkeit um 43 erhöhen. Der höhere der beiden Werte wird gewählt. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst von Pandaria (75)\nBenötigt Shado-Pan\n- Respektvoll\nVerkaufspreis:" }
