entries[84727] = { ["name"] = "Uralter Seelenstaub", ["text"] = "Questgegenstand\n\"Überreste eines uralten Yaungolgeistes. Bringt vier dieser Überreste zu einem uralten Leichnam, um den Geist zu befreien und ihn in sein nächstes Leben zu entlassen.\"" }
entries[84728] = { ["name"] = "Zügel des Scharlachroten Reitkranichs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren scharlachroten Reitkranich und entlässt ihn wieder.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:" }
entries[84753] = { ["name"] = "Zügel der Kafayaks", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares weißes Reityak und entlässt es wieder.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es ist ungeklärt, ob die Grummel dieses Yak nach seiner Farbe oder seinem Zweck benannten.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[84758] = { ["name"] = "Seltsam geformter Stein", ["text"] = "Wird beim Aufheben gebunden\n\"Irgendetwas an der Form dieses Steins lässt ihn... lebendig erscheinen.\"\nVerkaufspreis:" }
entries[84759] = { ["name"] = "Verschlüsselte Schriftrolle", ["text"] = "Questgegenstand\n\"Diese Schriftrolle, in uralter Tinte geschrieben, ist ganz offensichtlich nicht von Yaungol verfasst worden - oder zumindest nicht in einer ihrer Sprachen.\"" }
entries[84762] = { ["name"] = "Hochexplosives Yaungolöl", ["text"] = "Questgegenstand\nBenutzen: Wirft das hochexplosive Ölfass auf die Yaungol und Mantis auf dem Gai-Cho-Schlachtfeld. Kann beim Reiten verwendet werden.\n\"Der Name passt. Das Zeug hat rumms!\"" }
