entries[84792] = { ["name"] = "Ledertunika des bösartigen Gladiators", ["text"] = "Saison 12\nWird beim Aufheben gebunden\nBrust Leder\n7 Rüstung\n+2 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 4.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 4 Vielseitigkeit\n\nHaltbarkeit 165 / 165\nKlassen: Schurke\nGewänder des Gladiators (0/5)\nLedertunika des Gladiators\nLederhandschuhe des Gladiators\nLederhelm des Gladiators\nLederbeinschützer des Gladiators\nLederschiftung des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set : Erhöht Euren gesamten verursachten Schaden um 4%.\n(4) Set : Erhöht Eure maximale Energie um 30.\nVerkaufspreis:" }
entries[84793] = { ["name"] = "Zierratbrustschutz des bösartigen Gladiators", ["text"] = "Saison 12\nWird beim Aufheben gebunden\nBrust Platte\n16 Rüstung\n+2 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 1.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 4 Vielseitigkeit\n\nHaltbarkeit 165 / 165\nKlassen: Paladin\nErlösung des Gladiators (0/5)\nZierratbrustschutz des Gladiators\nZierrathandschuhe des Gladiators\nZierratkopfbedeckung des Gladiators\nZierratbeinplatten des Gladiators\nZierratschiftung des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set : Erhöht den Schaden und die Heilung Eures Zaubers 'Heiliger Schock' um 10%.\n(4) Set : Wenn Ihr 'Lichtblitz' wirkt, erhaltet Ihr 1 Heilige Kraft.\nVerkaufspreis:" }
